				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"O\'zbekistonda sayyohlik tashkilotchilari sifatida biz Yevropa agentliklari va sayohatchilarning kutishlari va ish usullarini bilamiz. Moslashuvchanlik, adaptivlik va xizmat sifati TourLink uchun markaziy qadriyatlardir."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Mehmonxonalarga bo\'lgan qarashimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Biz mehmonxonalarni qulaylik, estetika, atmosfera va jozibadorlik bo\'yicha tanlaymiz, ayniqsa butik mehmonxonalarni afzal ko\'ramiz. Hamkor mehmonxonalarimiz muntazam tekshiriladi. Katta shaharlarda biz markazga yaqin joylashuvni yoki tinch hududlarni afzal ko\'ramiz. Katta shaharlardagi transferlar tashkil etilgan va xizmatlarimiz tarkibiga kiritilgan."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Restoranlarga bo\'lgan qarashimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Restoranlar har bir bosqichning mahalliy xususiyatiga qarab tanlanadi. Biz an\'anaviy muassasalarni afzal ko\'ramiz va menyularni restoranlar bilan kelishamiz, shunda sayohatchilar har bir mintaqaning ta\'mlarini kashf qilishlari mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Transport xizmatimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Biz professional haydovchilar bilan transport vositalarini taqdim etamiz va sifatni muntazam nazorat qilamiz. Shaxsiy gidlar ehtiyotkorlik bilan tanlanadi va tez-tez baholanadi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Klassik va kengaytirilgan sayohatlar"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Klassik turlar O\'zbekistonning asosiy diqqatga sazovor joylarini qamrab oladi. Uzoqroq muddatga qolish uchun biz almashinuvdan so\'ng qo\'shimcha marshrutlar va shaxsiy takliflar berishimiz mumkin."}]}]}',
			pickup_description: null,
			additional_information:
				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ko\'rsatilgan mehmonxonalarda TWIN / DBL xonalarda joylashtirish."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalarda nonushta."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mineral suv, har bir kishiga tur kunida 1 litr."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrut bo\'yicha konditsionerli qulay transport va professional haydovchi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ingliz tilida so\'zlashuvchi hamroh gid guruh kelgandan to jo\'nab ketgunga qadar (10 kishidan boshlab guruhlar uchun)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ingliz tilida so\'zlashuvchi mahalliy gid ekskursiyalar uchun (1-9 kishilik guruhlar uchun)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Barcha ko\'rsatilgan yodgorliklarga kirish to\'lovlari, foto va video to\'lovlaridan tashqari."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Viza xarajatlari va rasmiylashtirish."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Fotosurat va video uchun to\'lovlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- To\'liq pansion (10 kishidan boshlab qo\'shimcha sifatida mavjud)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Xalqaro aviachiptalar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichki aviachiptalar, agar dasturda aniq ko\'rsatilmagan bo\'lsa."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichki poyezd chiptalari, agar dasturda aniq ko\'rsatilmagan bo\'lsa."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichimliklar va alkogol."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalar, aeroportlar va vokzallarda yuk tashish xizmati."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Sayohat va tibbiy sug\'urta."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Chiqimlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Shaxsiy xarajatlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- «Kiritilgan» bo\'limida ko\'rsatilmagan har qanday xizmatlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ushbu taklif bronlash tasdig\'i emas."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Iltimos, bronlashdan oldin xalqaro reyslarda joy mavjudligini tekshiring."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Agar ko\'rsatilgan mehmonxonalar mavjud bo\'lmasa, mavjudlikka qarab bir xil toifadagi mehmonxonalar taklif etiladi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichki reyslar va poyezdlar vaqt va mavjudlik o\'zgarishiga duchor bo\'lishi mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrut qismiga qarab turli xil transport vositalari va haydovchilardan foydalanish mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalardan foydalanish mavjudlikka bog\'liq; bron qilish mijoz tasdiqlagandan keyin amalga oshiriladi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- TourLink marshrutdagi ob-havo sharoitlari uchun javobgar emas."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Chiqimlar majburiy emas."}]}]}',
