			overview_description:
				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"O\'zbekiston bo\'ylab sayohat tashkilotchilari sifatida biz Yevropa agentliklari va sayohatchilarning kutishlari va ish tamoyillarini tushunamiz. Moslashuvchanlik, adaptivlik va xizmat sifati TourLinkning asosiy qadriyatlaridir."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Mehmonxonalarga bo\'lgan yondashuvimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Biz mehmonxonalarni qulaylik, estetika, atmosfera va xarakter darajasiga qarab tanlaymiz, butik mehmonxonalarni afzal ko\'ramiz. Hamkor mehmonxonalar muntazam tekshiriladi va lokatsiyani tanlashda biz markazga yaqinlik yoki katta shaharlarda dam olish uchun tinch hududni hisobga olamiz. Katta shaharlardagi transferlar tashkil etiladi va xizmatlarimiz tarkibiga kiradi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Restoranlarga bo\'lgan yondashuvimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Restoranlar marshrutning har bir bosqichining mahalliy xususiyatlarini hisobga olgan holda tanlanadi. Biz an\'anaviy muassasalarni afzal ko\'ramiz va menyularni restoranlar bilan kelishamiz, shunda mehmonlar har bir mintaqaning ta\'mlari bilan tanishadilar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Transport xizmatimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Biz professional haydovchilar bilan avtomobillarni taqdim etamiz va xizmat sifatini muntazam nazorat qilamiz. Shaxsiy gidlar ehtiyotkorlik bilan tanlanadi va davriy baholanadi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Klassik va kengaytirilgan sayohatlar"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Klassik turlar O\'zbekistonning asosiy shaharlari va diqqatga sazovor joylarini qamrab oladi. Uzoqroq sayohatlar uchun biz muhokamadan so\'ng qo\'shimcha marshrutlar va shaxsiy tavsiyalar taklif qilishimiz mumkin."}]}]}',
			pickup_description: null,
			additional_information:
				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ko\'rsatilgan mehmonxonalarda ikki kishilik (TWIN / DBL) joylashtirish."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalarda nonushta."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mineral suv, har bir kishiga tur kunida 1 litr."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrut bo\'yicha professional haydovchi bilan qulay konditsionerli transport:"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- 1-2 kishi: sedan, 5 o\'ringacha."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- 3-7 kishi: mikroavtobus, 11 o\'ringacha."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- 8-21 kishi: midi-avtobus, 31 o\'ringacha."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ekskursiyalar uchun mahalliy rus tilida so\'zlashuvchi gidlar (1-9 kishilik guruhlar uchun)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Barcha ko\'rsatilgan yodgorliklarga kirish chiptalari, foto va video to\'lovlaridan tashqari."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Poyezd chiptalari: Buxoro-Samarqand, Samarqand-Toshkent."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Agentlikning 24/7 yordami."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Viza xarajatlari va rasmiylashtirish."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Fotosurat va video uchun to\'lovlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- To\'liq pansion (10 kishidan boshlab qo\'shimcha sifatida mavjud)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Xalqaro aviachiptalar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Belgilangan tushlik yoki kechki ovqat menyularidagi qo\'shimcha xizmatlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichimliklar va alkogol."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalar, aeroportlar va vokzallarda porter xizmati."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Sayohat va tibbiy sug\'urta."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Chiqimlar va mukofotlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Shaxsiy xarajatlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- «Kiritilgan xizmatlar» bo\'limida ko\'rsatilmagan har qanday xizmatlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ushbu taklif bronlash tasdig\'i emas."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Bronlashdan oldin, xalqaro reyslarda joy mavjudligini tekshirib ko\'ring."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Agar dasturda ko\'rsatilgan mehmonxonalar bronlash sanasida mavjud bo\'lmasa, mavjudligiga qarab bir xil toifadagi yoki muqobil mehmonxonalar taklif etiladi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Erta kelish va kech ketish, agar dasturda aniq ko\'rsatilmagan bo\'lsa, kirmaydi. Qo\'shimcha to\'lovlar mijoz xalqaro reys vaqtlarini tasdiqlaganidan keyin taklif qilinishi mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Markaziy Osiyo mehmonxona standartlari Yevropa mehmonxona standartlaridan farq qilishi mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichki aviareyslar va poyezdlar jadvali va mavjudligi o\'zgarishi mumkin. Agar zikr etilgan reys yoki poyezd mavjud bo\'lmasa, TourLink tur dasturiga qarab qulay alternativani taklif qiladi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrut aviakompaniyalar reys jadvalini, ish kunlarini yoki marshrut shartlarini o\'zgartirsa, o\'zgartirilishi mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Poyezd chiptalari uchun pasport nusxalari turdan 45 kun oldin taqdim etilishi kerak."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrut temir yo\'l jadvallari yoki ish kunlari o\'zgarganda o\'zgartirilishi mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrut qismiga va zarur transport turiga qarab turli avtomobillar va haydovchilardan foydalanish mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Agar tashrif buyuriladigan joy tashrif buyuruvchilar uchun yopiq bo\'lsa, u muqobil bilan almashtiriladi. Yirik tadbirlar vaqtida turar joy o\'zgartirilishi va shunga o\'xshash toifaga almashtirilishi mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalarda turish mavjudligiga bog\'liq. Mijozdan tasdiq olinmaguncha bronlash amalga oshirilmaydi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- TourLink marshrut davomidagi ob-havo sharoitlari uchun javobgar emas."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Chiqimlar majburiy emas."}]}]}',
