				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"O\'zbekiston sehrini kashf eting — bu yerda jonli madaniyat, boy tarix va hayratlanarli arxitektura unutilmas sayohatni yaratish uchun birlashadi. Qadimiy Ipak yo\'li shaharlaridan tortib, jonli mahalliy bozorlargacha — har bir lahza go\'zallik, lazzat va sarguzashtga to\'la. Markaziy Osiyoning qalbini hech qachon bo\'lmagandek his eting."}]}]}',
			overview_description:
				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"O\'zbekistonda sayohat tashkilotchilari sifatida biz Yevropa agentliklari va sayyohlarning kutishlari va ish standartlarini yaxshi tushunamiz. Moslashuvchanlik, adaptivlik va xizmat sifati TourLink uchun asosiy qadriyatlardir."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Mehmonxonalarga bo\'lgan yondashuvimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Biz mehmonxonalarni qulaylik, estetika, atmosfera va jozibadorlikka qarab tanlaymiz, butik mehmonxonalarni afzal ko\'ramiz. Hamkor mehmonxonalarimiz muntazam tekshirib boriladi. Katta shaharlarda markazga yaqin yoki dam olish uchun qulay tinch hududlarni afzal ko\'ramiz. Katta shaharlardagi transferlar tashkil etiladi va xizmatlarimiz tarkibiga kiradi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Restoranlarga bo\'lgan yondashuvimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Restoranlar har bir to\'xtash joyining mahalliy xususiyatiga qarab tanlanadi. Biz an\'anaviy muassasalarni afzal ko\'ramiz va menyularni restoran jamoalari bilan kelishib, sayohatchilar har bir mintaqaning ta\'mlarini kashf etishlari mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Transport xizmatimiz"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Biz professional haydovchilar bilan transport vositalarini taqdim etamiz va muntazam sifat nazoratini olib boramiz. Shaxsiy gidlar ehtiyotkorlik bilan tanlanadi va tez-tez baholanib turiladi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Klassik va kengaytirilgan sayohatlar"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Klassik turlar O\'zbekistonning asosiy diqqatga sazovor joylarini qamrab oladi. Uzoqroq muddatli bo\'lish uchun biz muzokaralardan so\'ng qo\'shimcha marshrutlar va shaxsiy tavsiyalar taklif qilishimiz mumkin."}]}]}',
			pickup_description: null,
			additional_information:
				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ko\'rsatilgan mehmonxonalarda TWIN / DBL (ikki kishilik) joylashtirish."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalarda nonushta."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mineral suv, har bir tur kuni uchun har bir kishiga 1 litr."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrut bo\'yicha professional haydovchi bilan qulay konditsionerli transport."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Guruh kelgan paytdan boshlab jo\'nab ketguncha ingliz tilida so\'zlashuvchi hamroh gid (10 kishidan boshlab guruhlar uchun)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ekskursiyalar uchun ingliz tilida so\'zlashuvchi mahalliy gid (1-9 kishilik guruhlar uchun)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Barcha zikr etilgan yodgorliklarga kirish chiptalari, foto va video to\'lovlaridan tashqari."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Viza xarajatlari va rasmiylashtirish."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Fotosurat va video uchun to\'lovlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- To\'liq pansion (10 kishidan boshlab guruhlar uchun qo\'shimcha sifatida mavjud)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Xalqaro aviachiptalar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichki aviachiptalar, agar dasturda to\'g\'ridan-to\'g\'ri ko\'rsatilmagan bo\'lsa."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichki poyezd chiptalari, agar dasturda to\'g\'ridan-to\'g\'ri ko\'rsatilmagan bo\'lsa."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichimliklar va alkogol."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalar, aeroportlar va vokzallarda yuk tashuvchilar xizmati."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Sayohat va tibbiy sug\'urta."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Chiqimlar (chaqalar)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Shaxsiy xarajatlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- «Kiritilgan» bo\'limida ko\'rsatilmagan har qanday xizmatlar."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ushbu taklif bronlash tasdig\'i emas."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Bronlashdan oldin, xalqaro reyslarda joy mavjudligini tekshirib ko\'ring."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Agar dasturda ko\'rsatilgan mehmonxonalar mavjud bo\'lmasa, mavjudligiga qarab boshqa toifadagi mehmonxonalar taklif etiladi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Ichki aviareyslar va poyezdlar jadvali va mavjudligi o\'zgarishi mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Marshrutning turli qismlarida marshrut turiga va kerakli transport turiga qarab turli avtomobillar va haydovchilardan foydalanish mumkin."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Mehmonxonalarda turish mavjudligiga bog\'liq. Mijozdan tasdiq olinmaguncha bronlash amalga oshirilmaydi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- TourLink marshrut davomidagi ob-havo sharoitlari uchun javobgar emas."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Chiqimlar (chaqalar) majburiy emas."}]}]}',
			cancellation_policy:
				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Kelishdan 45 kun va undan ko\'proq oldin bekor qilish: bekor qilish to\'lovi olinmaydi."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Kelishdan 44-25 kun oldin bekor qilish: tur narxining 50%."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Kelishdan 24-15 kun oldin bekor qilish: tur narxining 75%."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"- Kelishdan 14-0 kun oldin bekor qilish: tur narxining 100%."}]}]}',
